export function compile(nodes){
 if(!Array.isArray(nodes)||nodes.length>512)throw Error('A circuit can contain at most 512 nodes.');
 const map=new Map(nodes.map(n=>[n.id,n]));if(map.size!==nodes.length)throw Error('Duplicate node ID.');
 const inputs=nodes.filter(n=>n.type==='input'),states=nodes.filter(n=>n.type==='mem'),outputs=nodes.filter(n=>n.type==='output');
 if(!outputs.length)throw Error('Add at least one output.');if(inputs.length>256||outputs.length>256)throw Error('Pin limit exceeded.');
 const signals=new Map();inputs.forEach((n,i)=>signals.set(n.id,2+i));states.forEach((n,i)=>signals.set(n.id,2+inputs.length+i));
 let next=2+inputs.length+states.length;const ops=[],visiting=new Set();
 function resolve(id){if(!id||!map.has(id))throw Error('Connect all input ports.');if(signals.has(id))return signals.get(id);if(visiting.has(id))throw Error('Cycle detected. Add a Settle node to the feedback path.');const n=map.get(id);if(n.type!=='nand')throw Error('Invalid signal source.');visiting.add(id);const a=resolve(n.ins[0]),b=resolve(n.ins[1]);visiting.delete(id);ops.push({op:'NAND',a:Math.min(a,b),b:Math.max(a,b)});signals.set(id,next++);return signals.get(id);}
 nodes.filter(n=>n.type==='nand').forEach(n=>resolve(n.id));const nextStateSources=states.map(n=>resolve(n.ins[0])),outputSources=outputs.map(n=>resolve(n.ins[0]));
 return {format:'acdv-ir',version:1,nInputs:inputs.length,localStateCount:states.length,ops,nextStateSources,outputSources,signals,inputs,states,outputs};
}
export function step(ir,state,inputs){if(state.length!==ir.localStateCount||inputs.length!==ir.nInputs)throw Error('Incorrect state or input length.');if([...state,...inputs].some(x=>x!==0&&x!==1))throw Error('Bit values must be 0 or 1.');const signals=[0,1,...inputs,...state];for(const op of ir.ops){if(op.a>=signals.length||op.b>=signals.length)throw Error('Forward reference.');signals.push(1-(signals[op.a]&signals[op.b]));}return {signals,outputs:ir.outputSources.map(x=>signals[x]),nextState:ir.nextStateSources.map(x=>signals[x])};}
export function encode(ir){const arr=[];function put(n,b){for(let i=b-1;i>=0;i--)arr.push(Math.floor(n/2**(8*i))&255);}arr.push(65,67,68,86);put(1,2);put(ir.nInputs,2);put(ir.outputSources.length,2);put(ir.localStateCount,2);put(ir.ops.length,4);for(const o of ir.ops){put(16,1);put(o.a,4);put(o.b,4);}for(const n of [...ir.nextStateSources,...ir.outputSources])put(n,4);return '0x'+arr.map(v=>v.toString(16).padStart(2,'0')).join('');}
export function validateDraft(obj){if(obj?.version!==1||!Array.isArray(obj.nodes)||obj.nodes.length>512)throw Error('Unsupported draft file.');const ids=new Set();for(const n of obj.nodes){if(typeof n.id!=='string'||!/^n\d+$/.test(n.id)||ids.has(n.id)||!['input','nand','mem','output'].includes(n.type))throw Error('Invalid node.');ids.add(n.id);if(!Number.isFinite(n.x)||!Number.isFinite(n.y)||n.x<0||n.y<0||n.x>2000||n.y>2000)throw Error('Invalid position.');if(!Array.isArray(n.ins)||n.ins.length!==({input:0,nand:2,mem:1,output:1}[n.type])||n.ins.some(s=>s!==null&&(typeof s!=='string'||!/^n\d+$/.test(s))))throw Error('Invalid connection.');if(n.type==='input'&&![0,1].includes(n.value))throw Error('Invalid bit.');}return obj.nodes;}
export function template(name='nand'){if(name==='memory')return [{id:'n1',type:'input',x:60,y:160,ins:[],value:1},{id:'n2',type:'mem',x:300,y:160,ins:['n1']},{id:'n3',type:'output',x:560,y:160,ins:['n2']}];if(name==='not')return [{id:'n1',type:'input',x:70,y:170,ins:[],value:0},{id:'n2',type:'nand',x:310,y:170,ins:['n1','n1']},{id:'n3',type:'output',x:560,y:170,ins:['n2']}];return [{id:'n1',type:'input',x:60,y:110,ins:[],value:0},{id:'n2',type:'input',x:60,y:290,ins:[],value:1},{id:'n3',type:'nand',x:320,y:200,ins:['n1','n2']},{id:'n4',type:'output',x:590,y:200,ins:['n3']}];}
